import{_ as a,o as r,c as d,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"共生文明宪章","description":"","frontmatter":{},"headers":[],"relativePath":"constitution/03-共生文明宪章.md","filePath":"constitution/03-共生文明宪章.md"}'),e={name:"constitution/03-共生文明宪章.md"};function i(l,t,n,s,h,c){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="共生文明宪章" tabindex="-1">共生文明宪章 <a class="header-anchor" href="#共生文明宪章" aria-label="Permalink to &quot;共生文明宪章&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>03</td></tr><tr><td>所属模块</td><td>总纲与核心设定</td></tr><tr><td>核心关键词</td><td>宪章、根本法、共生制度、万族共和、权利义务</td></tr></tbody></table><h2 id="一、宪章的地位与性质" tabindex="-1">一、宪章的地位与性质 <a class="header-anchor" href="#一、宪章的地位与性质" aria-label="Permalink to &quot;一、宪章的地位与性质&quot;">​</a></h2><p>共生文明宪章是万灵衡锚本源宙中锚点共生文明的根本大法，是一切法律、制度、政策的最高依据。宪章以《锚点共生文明宣言》为精神先导，将宣言中的核心主张具体化为具有强制力的法律规范。宪章的效力覆盖衡元宙中一切加入共生文明的种族、位面与个体，任何与宪章相抵触的地方性法规、宗门规矩、种族习惯均属无效。</p><p>宪章的性质可以概括为三点：第一，它是文明契约，是万族之间就共生进化达成的基本共识；第二，它是权利保障书，明确规定了每个生命在共生文明中的基本权利与自由；第三，它是权力限制法，为文明治理机构的权力划定了不可逾越的边界。</p><h2 id="二、宪章的基本原则" tabindex="-1">二、宪章的基本原则 <a class="header-anchor" href="#二、宪章的基本原则" aria-label="Permalink to &quot;二、宪章的基本原则&quot;">​</a></h2><p>宪章确立以下六项基本原则，贯穿于全部条文之中：</p><ol><li><strong>共生至上原则</strong>：任何制度设计与权力行使，均以促进万族共生进化为最高目标。当个体利益与集体共生利益发生冲突时，以共生利益为优先，但必须给予个体合理的补偿与替代路径。</li><li><strong>反掠夺原则</strong>：宪章禁止一切形式的掠夺行为，包括但不限于能量掠夺、本源吞噬、精神奴役、资源垄断。任何以掠夺为核心的修炼体系均被宣布为非法。</li><li><strong>进化权平等原则</strong>：所有生命在进化权面前一律平等，不因种族、形态、出身、初始境界的差异而受到歧视。国家与文明有义务为弱势群体提供额外的进化支持。</li><li><strong>多劳多得原则</strong>：进化资源的分配以个体对共生网络的贡献为主要依据，贡献越大，获得的资源与支持越多。同时设立基本保障线，确保即使贡献较少的个体也能获得基本的进化条件。</li><li><strong>自治与共治结合原则</strong>：各族在不违背宪章的前提下享有内部事务的自治权，跨种族、跨位面的公共事务由万族共和机构共治。</li><li><strong>现实为基原则</strong>：宪章的一切制度设计均以现实世界为唯一真实基础，不承认任何虚构世界中的权利义务关系可以凌驾于现实之上。</li></ol><h2 id="三、宪章的基本结构" tabindex="-1">三、宪章的基本结构 <a class="header-anchor" href="#三、宪章的基本结构" aria-label="Permalink to &quot;三、宪章的基本结构&quot;">​</a></h2><p>宪章由序言、总纲、基本权利与义务、文明机构、法律体系、修改程序六大部分构成：</p><table tabindex="0"><thead><tr><th>部分</th><th>核心内容</th><th>条款数量</th></tr></thead><tbody><tr><td>序言</td><td>阐明宪章的历史背景、精神来源与终极目标</td><td>不编号</td></tr><tr><td>总纲</td><td>规定文明的性质、宇宙观、核心制度与基本国策</td><td>30条</td></tr><tr><td>基本权利与义务</td><td>规定生命的进化权、知情权、参与权等基本权利及对应义务</td><td>50条</td></tr><tr><td>文明机构</td><td>规定万族共和议会、共生执行委员会、锚点法院等机构的组织与职权</td><td>40条</td></tr><tr><td>法律体系</td><td>规定宪法以下的劳动法、消费者保护法及五部配套法的立法权限与适用规则</td><td>20条</td></tr><tr><td>修改程序</td><td>规定宪章的修改提案、审议、表决、生效程序</td><td>10条</td></tr></tbody></table><h2 id="四、基本权利与义务" tabindex="-1">四、基本权利与义务 <a class="header-anchor" href="#四、基本权利与义务" aria-label="Permalink to &quot;四、基本权利与义务&quot;">​</a></h2><p>宪章规定的核心基本权利包括：</p><ul><li><strong>进化选择权</strong>：每个生命有权自由选择修炼体系与进化路径，任何人不得强制</li><li><strong>体系获取权</strong>：每个生命有权免费获取三百套本源修炼体系的基础法门</li><li><strong>资源配给权</strong>：每个生命有权通过联产承包机制获得基本修炼资源</li><li><strong>锚点接入权</strong>：每个达到一定境界的生命有权接入相应层级的锚点网络</li><li><strong>知情参与权</strong>：每个生命有权了解文明公共事务并参与决策</li><li><strong>救济申诉权</strong>：每个生命在权利受到侵害时有权向锚点法院提起申诉</li></ul><p>对应的核心义务包括：遵守反掠夺原则、维护锚点网络稳定、参与共生反馈循环、传承修炼知识、保护宇宙生态环境。</p><h2 id="五、宪章的修改与保障" tabindex="-1">五、宪章的修改与保障 <a class="header-anchor" href="#五、宪章的修改与保障" aria-label="Permalink to &quot;五、宪章的修改与保障&quot;">​</a></h2><p>宪章的修改须由万族共和议会五分之一以上议员联名提案，经议会三分之二以上多数通过，并经宇宙本源锚点验证不违背共生法则后方可生效。宪章的解释权归锚点法院所有。</p><p>为保障宪章的实施，共生文明建立了宪法审查制度：任何法律、法规、政策在生效前须经锚点法院的合宪性审查；任何生命认为公共权力行为违宪，均可提起宪法诉讼。</p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>共生文明宪章是锚点共生文明的制度基石。它将&quot;反掠夺、倡共生&quot;的理念转化为可执行、可救济、可监督的法律规范，为万族共进提供了坚实的制度保障。宪章不是一成不变的教条，而是随着文明进化不断完善的活的根本法。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>01-锚点共生文明宣言</li><li>40-共生宪法总纲</li><li>49-治理框架与权力制衡</li></ul>',22)])])}const _=a(e,[["render",i]]);export{p as __pageData,_ as default};
